// Generic nested loop skeleton - adapt bounds and print condition
for (let i = 1; i <= n; i++) {
  let row = '';

  // leading spaces (for centered/pyramid patterns: n-i spaces)
  for (let s = 0; s < n - i; s++) row += ' ';

  // main content: j bound determines shape
  for (let j = 1; j <= i; j++) {         // right triangle: j <= i
    // for inverted: j <= n - i + 1
    // for rectangle: j <= m
    // for hollow: only print on border
    const onBorder = (i === 1 || i === n || j === 1 || j === i);
    row += onBorder ? '* ' : '  ';
  }

  console.log(row.trimEnd());
}
